import raw from "@/data/elk-hunt-areas.json";
import { DemandDraw, MapArea, PointsDraw, RegionDraws, neighborsIn } from "@/lib/hunts";

// Generated by scripts/hunts/build_hunt_data.py from WGFD's draw reports and
// hunt-area boundaries. Server-only: the file is ~400 KB with geometry, so
// pages pass the slices they need to client components, never this module.

export interface ElkHunt {
  type: string;
  description: string;
  cowCalf: boolean;
  nrPoints?: PointsDraw;
  nrSpecialPoints?: PointsDraw;
  nrRandom?: DemandDraw;
  nrSpecialRandom?: DemandDraw;
  nrCowCalf?: DemandDraw;
  resident?: DemandDraw;
  residentCowCalf?: DemandDraw;
}

export interface ElkArea extends MapArea {
  herdUnit: number;
  herdName: string;
  region: string;
  sqMiles: number;
  hunts: ElkHunt[];
}

interface ElkData {
  year: number;
  sources: { odds: string; boundaries: string };
  nrRegions: Record<string, RegionDraws>;
  areas: ElkArea[];
}

const data = raw as unknown as ElkData;

export const ELK_YEAR = data.year;
export const ELK_SOURCES = data.sources;
export const ELK_AREAS = data.areas;

export const elkSlug = (a: Pick<ElkArea, "area">) => `area-${a.area}`;
export const elkPath = (a: Pick<ElkArea, "area">) => `/hunting/elk/${elkSlug(a)}`;

export function getElkArea(slug: string): ElkArea | undefined {
  const m = /^area-(\d+)$/.exec(slug);
  return m ? ELK_AREAS.find((a) => a.area === Number(m[1])) : undefined;
}

// The headline hunt for an area: the first "any elk" type, else the first hunt.
export function mainHunt(a: ElkArea): ElkHunt | undefined {
  return a.hunts.find((h) => !h.cowCalf && /any elk/i.test(h.description)) ?? a.hunts[0];
}

export const neighbors = (a: ElkArea) => neighborsIn(ELK_AREAS, a);
